1	// src/lib/indexsteuerung.js – Indexsteuerung (Welle 1, Paket I)
2	//
3	// Reine Funktionen ohne Importe, damit sie in site.js, robots.js, sitemap.js
4	// und in Unit-Tests (node:test) gleich verwendet werden können.
5	//
6	//  1. ermittleSiteUrl(): Produktions-Build OHNE NEXT_PUBLIC_SITE_URL bricht ab
7	//     (Masterplan Abschnitt 3, S-Minus: einzige erlaubte Build-Sperre dieser Art).
8	//     `next build` und `next start` laufen immer mit NODE_ENV=production; site.js
9	//     wird beim Sammeln der Seitendaten ausgewertet, der Fehler beendet den Build.
10	//  2. istIndexierbar(): Indexierung NUR, wenn alles zusammenpasst – Produktions-
11	//     Build, ausdrücklich NEXT_PUBLIC_SITE_ENV=production UND die Produktions-
12	//     domain. Alles andere (Staging, Vorschau, lokaler Build, vergessene
13	//     Variable) liefert noindex. Fehlertolerant in Richtung „nicht indexieren“.
14	//  3. robotsRegeln(): Crawler-Regeln nach Entscheidung E5.
15	//  4. ohneEntwuerfe(): Entwurfsseiten gehören nicht in die Sitemap.
16	
17	/** Produktions-URL (Entscheidung E1, Inhaber): oekoinvest.com, mit www. */
18	export const PRODUKTIONS_URL = "https://www.oekoinvest.com";
19	
20	/** Erlaubte Werte für NEXT_PUBLIC_SITE_ENV (nur "production" wird indexiert). */
21	export const UMGEBUNGEN = ["production", "staging", "preview", "development"];
22	
23	/**
24	 * Basis-URL der Website ermitteln und prüfen.
25	 *
26	 * @param {{ siteUrl?: string, nodeEnv?: string }} e
27	 *   siteUrl = process.env.NEXT_PUBLIC_SITE_URL, nodeEnv = process.env.NODE_ENV
28	 *   (bewusst einzeln übergeben: Next.js ersetzt nur ausgeschriebene
29	 *   process.env.NEXT_PUBLIC_…-Zugriffe, nicht das ganze process.env-Objekt).
30	 * @returns {string} Origin ohne abschließenden Schrägstrich, z. B. "https://www.oekoinvest.com"
31	 * @throws {Error} in Produktion ohne Wert sowie bei ungültigem Wert (jede Umgebung)
32	 */
33	export function ermittleSiteUrl({ siteUrl, nodeEnv } = {}) {
34	  const roh = typeof siteUrl === "string" ? siteUrl.trim() : "";
35	
36	  if (!roh) {
37	    if (nodeEnv === "production") {
38	      throw new Error(
39	        "NEXT_PUBLIC_SITE_URL fehlt. In Produktions-Builds (next build/next start) muss die Basis-URL gesetzt sein, " +
40	          `z. B. NEXT_PUBLIC_SITE_URL=${PRODUKTIONS_URL} (Staging: eigene URL). Siehe .env.example.`,
41	      );
42	    }
43	    // Entwicklung und Tests: Produktions-URL als Vorgabe, damit Canonicals,
44	    // Sitemap und JSON-LD lokal genauso aussehen wie später live.
45	    return PRODUKTIONS_URL;
46	  }
47	
48	  let url;
49	  try {
50	    url = new URL(roh);
51	  } catch {
52	    throw new Error("NEXT_PUBLIC_SITE_URL ist keine gültige absolute URL (erwartet z. B. https://www.oekoinvest.com).");
53	  }
54	  if (url.protocol !== "https:" && url.protocol !== "http:") {
55	    throw new Error("NEXT_PUBLIC_SITE_URL muss mit https:// (lokal auch http://) beginnen.");
56	  }
57	  if (url.username || url.password || url.search || url.hash || (url.pathname && url.pathname !== "/")) {
58	    // abs() hängt Pfade direkt an – ein Pfadanteil oder Zugangsdaten in der
59	    // Basis-URL würden in Canonicals, Sitemap und robots.txt landen.
60	    throw new Error("NEXT_PUBLIC_SITE_URL darf nur Schema und Host enthalten (kein Pfad, keine Parameter, keine Zugangsdaten).");
61	  }
62	  return url.origin;
63	}
64	
65	/**
66	 * Darf diese Auslieferung indexiert werden?
67	 * @param {{ nodeEnv?: string, siteEnv?: string, siteUrl?: string }} e
68	 */
69	export function istIndexierbar({ nodeEnv, siteEnv, siteUrl } = {}) {
70	  return nodeEnv === "production" && siteEnv === "production" && siteUrl === PRODUKTIONS_URL;
71	}
72	
73	/**
74	 * Pfade, die für ALLE Crawler gesperrt sind (E5: Portal und Einladungen bleiben
75	 * gesperrt). /einladung/ und /angebot/ tragen persönliche Token bzw. Briefcodes
76	 * in der URL; sie werden nirgends öffentlich verlinkt, also ist die Sperre hier
77	 * richtig (die Seiten tragen zusätzlich noindex). /login, /registrieren usw.
78	 * bleiben abrufbar, damit Suchmaschinen deren noindex sehen.
79	 */
80	export const GESPERRT_FUER_ALLE = ["/api/", "/portal", "/einladung/", "/angebot/"];
81	
82	/**
83	 * Öffentliche Wissensseiten, die GPTBot und Google-Extended nutzen dürfen (E5).
84	 * Bewusst NICHT enthalten: /energie-live (Datenlizenzen SMARD/aWATTar ungeklärt,
85	 * Masterplan S2), Rechner, Projektbörse, Formulare.
86	 */
87	export const WISSENSSEITEN = [
88	  "/ratgeber",
89	  "/wissen/",
90	  "/regionen",
91	  "/faq",
92	  "/marktdaten",
93	  // Ländermodell: dieselben Seiten in den Länderfassungen /de, /at, /ch
94	  ...["de", "at", "ch"].flatMap((l) => [`/${l}/ratgeber`, `/${l}/wissen/`, `/${l}/regionen`, `/${l}/faq`, `/${l}/marktdaten`]),
95	  "/llms.txt",
96	];
97	
98	/** Trainingscrawler mit Wissensseiten-Freigabe (E5, Antwort 2 „Ja“). */
99	export const TRAINING_WISSEN = ["GPTBot", "Google-Extended"];
100	
101	/**
102	 * Vollständig gesperrt. CCBot und Bytespider laut E5; Meta-ExternalAgent und
103	 * cohere-ai waren schon gesperrt und sind von E5 nicht erfasst – Sperre bleibt
104	 * bis zur Entscheidung des Inhabers.
105	 */
106	export const GESPERRT = ["CCBot", "Bytespider", "Meta-ExternalAgent", "cohere-ai"];
107	
108	/**
109	 * Regeln für src/app/robots.js (MetadataRoute.Robots).
110	 *
111	 * Such- und Abrufcrawler (Googlebot, Bingbot, OAI-SearchBot, ChatGPT-User,
112	 * PerplexityBot, Claude-SearchBot, Claude-User …) fallen unter "*" und sind
113	 * damit für alle öffentlichen Seiten erlaubt (E5, Antwort 1 „Ja“). Sie
114	 * bekommen bewusst keine eigene Gruppe: Eine eigene Gruppe ersetzt "*"
115	 * vollständig, und jede Abweichung wäre eine Fehlerquelle.
116	 *
117	 * Nicht-Produktion: alles gesperrt, keine Sitemap. Die eigentliche Absicherung
118	 * von Staging ist Basic-Auth auf Hosting-Ebene (W0-4); zusätzlich trägt jede
119	 * Seite noindex (src/app/layout.js).
120	 *
121	 * @param {{ indexierbar: boolean, siteUrl: string, sitemaps?: string[] }} e
122	 *   sitemaps: optionale Liste absoluter Sitemap-URLs; ohne Angabe die eine Sitemap unter
123	 *   /sitemap.xml (Ländermodell: eine Sitemap mit gemeinsamen Seiten und Länderfassungen)
124	 */
125	export function robotsRegeln({ indexierbar, siteUrl, sitemaps }) {
126	  if (!indexierbar) {
127	    return { rules: [{ userAgent: "*", disallow: "/" }] };
128	  }
129	  return {
130	    rules: [
131	      { userAgent: "*", allow: ["/", "/_next/image"], disallow: GESPERRT_FUER_ALLE },
132	      { userAgent: TRAINING_WISSEN, allow: WISSENSSEITEN, disallow: "/" },
133	      { userAgent: GESPERRT, disallow: "/" },
134	    ],
135	    sitemap: Array.isArray(sitemaps) && sitemaps.length ? sitemaps : `${siteUrl}/sitemap.xml`,
136	  };
137	}
138	
139	/**
140	 * Entwurfsseiten (sichtbar als ENTWURF markiert, noch nicht rechtlich
141	 * freigegeben). Nach Freigabe durch Strang R hier austragen.
142	 *  - /nutzungsbedingungen: ENTWURF = true in src/app/nutzungsbedingungen/page.js
143	 *  - /datenschutz: „ENTWURF zur datenschutzrechtlichen Prüfung“, Platzhalter offen
144	 *  - /bedingungen/*: FREIGEGEBEN = false in src/app/bedingungen/_teile.js
145	 */
146	export const ENTWURFSSEITEN = ["/nutzungsbedingungen", "/datenschutz", "/bedingungen"];
147	
148	/** true, wenn der Pfad eine Entwurfsseite oder darunter liegt. */
149	export function istEntwurf(pfad) {
150	  return ENTWURFSSEITEN.some((e) => pfad === e || pfad.startsWith(`${e}/`));
151	}
152	
153	/** Filtert Sitemap-Einträge ({ pfad }) ohne Entwurfsseiten. */
154	export function ohneEntwuerfe(eintraege) {
155	  return eintraege.filter((e) => !istEntwurf(e.pfad));
156	}
157	
158	/**
159	 * Sprache der Seite nach Pfad (wie <html lang> der Root-Layouts, Ländermodell):
160	 * /en… → "en", /de… → "de-DE", /at… → "de-AT", /ch… → "de-CH", sonst (gemeinsame Seite) "de".
161	 * Die Root-Layouts setzen lang serverseitig (src/components/Wurzel/Wurzel.js); diese Funktion
162	 * spiegelt das für Prüfskripte und Tests.
163	 */
164	export function spracheFuerPfad(pfad) {
165	  if (typeof pfad !== "string") return "de";
166	  if (/^\/en(\/|$)/.test(pfad)) return "en";
167	  const land = /^\/(de|at|ch)(\/|$)/.exec(pfad);
168	  return land ? `de-${land[1].toUpperCase()}` : "de";
169	}
