1	// src/app/sitemap.js
2	//
3	// Sitemap der ÖkoInvest-Website unter /sitemap.xml (wie vor Welle 2), Ländermodell:
4	//  - jede indexierbare gemeinsame Seite aus dem Register (src/lib/land/seiten.js), ohne Entwürfe
5	//    (ENTWURFSSEITEN in src/lib/indexsteuerung.js), mit Regionsseiten,
6	//  - dazu jede Länderfassung (/de, /at, /ch) mit ECHTEM eigenem Länderinhalt (LAENDERINHALT),
7	//    jeweils mit hreflang-Cluster (src/lib/land/sitemaps.js) – Länderfassungen ohne eigenen
8	//    Inhalt tragen noindex und fehlen hier,
9	//  - die übersetzten englischen Fassungen (/en/…, Register src/lib/sprache/seiten.js) mit demselben
10	//    hreflang-Cluster, alle Ratgeber-Artikel und, sofern das Plattform-Backend verfügbar
11	//    ist, die öffentlichen Exposés der Projektbörse.
12	//
13	// Portal, Login/Registrierung, /angebot, /einladung, /termin/verwalten, /bericht, /p und die
14	// Entwürfe unter /bedingungen gehören nicht in die Sitemap bzw. sind über robots.txt gesperrt.
15	
16	import { alleArtikel, artikelPfad } from "@/lib/ratgeber";
17	import { LEXIKON_STAND } from "@/data/lexikon";
18	import { abs } from "@/data/site";
19	import { sichtbareProjekte } from "@/lib/boerse/sichtbarkeit";
20	import { START, SPRACHMODELL, seitenEintraege } from "@/lib/land/sitemaps";
21	import { fassungIndexierbar, hreflang, seitenPfad } from "@/lib/land/pfad";
22	
23	/**
24	 * Öffentliche Exposés der Projektbörse aus dem Plattform-Backend
25	 * (src/lib/plattform/backend: backend().boerse(null, filter) -> { projekte, demo }).
26	 * Fehlt das Backend, ist es nicht konfiguriert (HTTP 503) oder antwortet es
27	 * nicht, bleibt die Sitemap trotzdem vollständig – nur ohne Projektseiten.
28	 * Demo-Daten landen bewusst nie in der Sitemap.
29	 */
30	async function projektEintraege() {
31	  try {
32	    const modul = await import("@/lib/plattform/backend");
33	    const impl = typeof modul.backend === "function" ? modul.backend() : modul;
34	    if (typeof impl?.boerse !== "function") return [];
35	    const antwort = await Promise.race([
36	      impl.boerse(null, {}),
37	      new Promise((_, nein) => setTimeout(() => nein(new Error("Zeitüberschreitung")), 5000)),
38	    ]);
39	    if (antwort?.demo) return [];
40	    const liste = Array.isArray(antwort) ? antwort : antwort?.projekte || [];
41	    // QM Welle 1: Test- und Demo-Datensätze nie in die Sitemap (src/lib/boerse/sichtbarkeit.js)
42	    return sichtbareProjekte(liste, { demo: false })
43	      .filter((p) => p && typeof p.slug === "string" && /^[a-z0-9-]+$/.test(p.slug))
44	      .map((p) => {
45	        const d = new Date(p.geaendertAm || p.aktualisiert || p.veroeffentlichtAm || p.modified || START);
46	        return {
47	          url: abs(`/projektboerse/${p.slug}`),
48	          lastModified: Number.isNaN(d.getTime()) ? START : d,
49	          changeFrequency: "weekly",
50	          priority: 0.6,
51	        };
52	      });
53	  } catch {
54	    return [];
55	  }
56	}
57	
58	export default async function sitemap() {
59	  const seiten = seitenEintraege({ lexikonStand: LEXIKON_STAND });
60	  // Ratgeber-Artikel; einzeln übersetzte (UEBERSETZT_EINZELN) zusätzlich unter /en mit hreflang-Cluster
61	  const ratgeber = alleArtikel().flatMap((a) => {
62	    const pfad = artikelPfad(a.slug);
63	    const basis = { lastModified: new Date(a.aktualisiert), changeFrequency: "monthly", priority: 0.7 };
64	    if (!fassungIndexierbar(pfad, null, "en")) return [{ url: abs(pfad), ...basis }];
65	    const alternates = { languages: hreflang(pfad) };
66	    return [
67	      { url: abs(pfad), ...basis, alternates },
68	      { url: abs(seitenPfad(pfad, null, "en")), ...basis, lastModified: SPRACHMODELL, alternates },
69	    ];
70	  });
71	  return [...seiten, ...ratgeber, ...(await projektEintraege())];
72	}
