1	// src/lib/land/pfad.js – Pfade, Länder- und Sprachwechsel, canonical und hreflang
2	//
3	// URL-Struktur (Ländermodell + Sprachmodell, Vorgabe des Inhabers): Sprache vor Land vor Seite.
4	//   /<seite>              Deutsch, gemeinsam (x-default)      /en/<seite>          Englisch, gemeinsam
5	//   /de|at|ch/<seite>     Deutsch, Land                       /en/de|at|ch/<seite> Englisch, Land
6	// Der Seitenpfad ist in allen Fassungen GLEICH (deutsche Pfade wie vor Welle 2).
7	//
8	// Schlüssel = Pfad OHNE Sprach- und Länderpräfix ("/rechner/pacht").
9	//   pfad("/rechner/pacht")                  → "/rechner/pacht"        (gemeinsame Seite)
10	//   pfad("/rechner/pacht", "AT")            → "/at/rechner/pacht"
11	//   pfad("/rechner/pacht", "AT", "en")      → "/en/at/rechner/pacht"
12	//   pfad("/", "CH")                         → "/ch"          pfad("/", null, "en") → "/en"
13	//   pfad("/portal", "AT", "en")             → "/portal"      (keine Länder-/Sprachfassung)
14	//   pfad("/wissen/ratgeber/x", "DE")        → "/de/ratgeber/x"   (Welle-2-Name aufgelöst)
15	//   pfad("/de/rechner/pacht", "AT")         → "/at/rechner/pacht" (Präfix wird ersetzt)
16	// Sprache: ohne Angabe die des übergebenen Pfades ("/en/…" → en), sonst Deutsch.
17	// Query und Anker bleiben erhalten. Links in Komponenten brauchen pfad() nicht: Die
18	// Link-Komponente src/components/Land/Link.js hängt Sprache und Land der Seite selbst an.
19	
20	import { abs } from "../../data/site.js";
21	import { LAENDER, PRAEFIX_MUSTER, landAusPraefix, landCode } from "./laender.js";
22	import { eigenerInhalt, hatLandfassung, indexierbar, laenderMitInhalt } from "./seiten.js";
23	import { nurPfad, umbenannt } from "./zonen.js";
24	import { SPRACH_INFO, SPRACH_MUSTER, ohneSprache, sprachCode, spracheAusPfad } from "../sprache/sprachen.js";
25	import { enLandInhalt, uebersetztIndexierbar } from "../sprache/seiten.js";
26	
27	const zerlege = (roh) => {
28	  const s = String(roh ?? "");
29	  const i = s.search(/[?#]/);
30	  return i < 0 ? [s, ""] : [s.slice(0, i), s.slice(i)];
31	};
32	
33	/**
34	 * Pfad einer Seite in Land und Sprache, ohne Prüfung.
35	 * seitenPfad("/rechner/pacht", "AT", "en") → "/en/at/rechner/pacht"; seitenPfad("/", null, "de") → "/"
36	 */
37	export function seitenPfad(schluessel, land = null, sprache = "de") {
38	  const l = landCode(land);
39	  const s = sprachCode(sprache) || "de";
40	  const p = `${SPRACH_INFO[s].praefix}${l ? LAENDER[l].einstieg : ""}${schluessel === "/" ? "" : schluessel}`;
41	  return p || "/";
42	}
43	
44	/** Pfad einer Seite in einem Land (Deutsch), ohne Prüfung ("/rechner/pacht", "AT" → "/at/rechner/pacht"). */
45	export const landPfad = (schluessel, land, sprache = "de") => seitenPfad(schluessel, land, sprache);
46	
47	/**
48	 * Wo befindet sich ein Pfad?
49	 * @returns {{ sprache: "de"|"en", land: "DE"|"AT"|"CH"|null, schluessel: string }} schluessel ohne Präfixe ("/" = Startseite)
50	 */
51	export function landAusPfad(pathname) {
52	  const roh = nurPfad(pathname);
53	  const sprache = spracheAusPfad(roh);
54	  const p = nurPfad(ohneSprache(roh));
55	  const m = PRAEFIX_MUSTER.exec(p);
56	  if (m) {
57	    const rest = p.slice(m[0].length);
58	    return { sprache, land: landAusPraefix(m[1]), schluessel: rest || "/" };
59	  }
60	  return { sprache, land: null, schluessel: p };
61	}
62	
63	/**
64	 * Ziel eines internen Links in Land und Sprache (land null = gemeinsame Seite).
65	 * Externe Links, Anker und Pfade ohne Länder-/Sprachfassung (Portal, Login …) bleiben unverändert;
66	 * ein vorhandenes Länderpräfix fällt dort weg.
67	 * @param {string} roh
68	 * @param {string|null} [land]
69	 * @param {"de"|"en"} [sprache] ohne Angabe: Sprache des Pfades
70	 */
71	export function pfad(roh, land = null, sprache) {
72	  if (typeof roh !== "string" || !roh.startsWith("/") || roh.startsWith("//")) return roh;
73	  const [p, rest] = zerlege(roh);
74	  const { sprache: s0, schluessel: k0 } = landAusPfad(p);
75	  const schluessel = umbenannt(k0) || k0;
76	  const s = sprachCode(sprache) || s0;
77	  if (!hatLandfassung(schluessel)) return (PRAEFIX_MUSTER.test(ohneSprache(p)) ? schluessel : p) + rest;
78	  return seitenPfad(schluessel, land, s) + rest;
79	}
80	
81	/** Link-Ziel als Objekt (Kompatibilität mit Welle 2): { href, label }. */
82	export function linkFuer(schluessel, land, label) {
83	  return { href: pfad(schluessel, land), label, giltFuer: null };
84	}
85	
86	/** Einstiegsseite eines Landes ("/at"); ohne Land die gemeinsame Startseite "/". */
87	export const einstieg = (land, sprache = "de") => pfad("/", land, sprache);
88	
89	/**
90	 * Länderwechsler: dieselbe Seite im anderen Land, in derselben Sprache.
91	 * Von Seiten ohne Länderfassung (Login …) führt die Wahl auf die Startseite des Landes.
92	 * @returns {{ href: string, art: "entsprechung"|"einstieg" }}
93	 */
94	export function entsprechung(pathname, zielLand) {
95	  const l = landCode(zielLand) || "DE";
96	  const { sprache, schluessel } = landAusPfad(pathname);
97	  if (!hatLandfassung(schluessel)) return { href: seitenPfad("/", l, sprache), art: "einstieg" };
98	  return { href: seitenPfad(schluessel, l, sprache), art: "entsprechung" };
99	}
100	
101	/**
102	 * Sprachwechsler: dieselbe Seite im selben Land in der anderen Sprache.
103	 * Von Seiten ohne Sprachfassung (Login, Portal …) auf die Startseite der Sprache.
104	 * @returns {{ href: string, art: "entsprechung"|"einstieg" }}
105	 */
106	export function sprachEntsprechung(pathname, zielSprache) {
107	  const s = sprachCode(zielSprache) || "de";
108	  const { land, schluessel } = landAusPfad(pathname);
109	  if (!hatLandfassung(schluessel)) return { href: seitenPfad("/", null, s), art: "einstieg" };
110	  return { href: seitenPfad(schluessel, land, s), art: "entsprechung" };
111	}
112	
113	/** Englische Fassung indexierbar und im Cluster? (übersetzt; Länderfassung nur mit EN-Länderinhalt) */
114	const enImCluster = (schluessel, land) => (land ? enLandInhalt(schluessel, land) : uebersetztIndexierbar(schluessel));
115	
116	/**
117	 * hreflang-Cluster einer Seite: die gemeinsame deutsche Seite als x-default, jede deutsche
118	 * Länderfassung mit eigenem Inhalt (de-DE, de-AT, de-CH) und – sobald übersetzt – die englische
119	 * Fassung ("en"; Länderfassungen "en-AT" … erst mit EN_LAENDERINHALT). Bidirektional: Alle
120	 * Mitglieder liefern dieselbe Tabelle. Ohne weitere Mitglieder: {} (die gemeinsame Seite steht allein).
121	 * @param {string} schluessel
122	 * @param {Record<string,string>} [weitere] zusätzliche Einträge (Altbestand)
123	 */
124	export function hreflang(schluessel, weitere = {}) {
125	  const laender = laenderMitInhalt(schluessel);
126	  const extra = Object.entries(weitere || {}).filter(([k]) => k !== "x-default");
127	  const en = enImCluster(schluessel, null);
128	  const enLaender = laender.filter((l) => enImCluster(schluessel, l));
129	  if (!laender.length && !extra.length && !en) return {};
130	  const tabelle = {};
131	  if (en) tabelle.de = abs(schluessel);
132	  for (const l of laender) tabelle[LAENDER[l].lang] = abs(seitenPfad(schluessel, l));
133	  if (en) tabelle.en = abs(seitenPfad(schluessel, null, "en"));
134	  for (const l of enLaender) tabelle[`en-${l}`] = abs(seitenPfad(schluessel, l, "en"));
135	  for (const [k, v] of extra) tabelle[k] = v;
136	  tabelle["x-default"] = abs(schluessel);
137	  return tabelle;
138	}
139	
140	/** Ist diese Fassung Mitglied ihres hreflang-Clusters (eigener Inhalt bzw. übersetzt)? */
141	export function imCluster(schluessel, land = null, sprache = "de") {
142	  const l = landCode(land);
143	  if (sprache === "en") return enImCluster(schluessel, l);
144	  return l ? eigenerInhalt(schluessel, l) : true;
145	}
146	
147	/**
148	 * Indexierbar in Land und Sprache? Gemeinsame deutsche Seite: laut Register (index: false = nie);
