216	export function eigenerInhalt(schluessel, land) {
217	  const s = seiteFuer(schluessel);
218	  if (!s || !LAND_CODES.includes(land)) return false;
219	  return Object.hasOwn(LAENDERINHALT[land], s.muster);
220	}
