227	 * Länderfassung nur mit eigenem Inhalt (sonst noindex bis zur Freigabe).
228	 */
229	export function indexierbar(schluessel, land = null) {
230	  const s = seiteFuer(schluessel);
231	  if (!s || s.eintrag.index === false) return false;
232	  return land ? eigenerInhalt(schluessel, land) : true;
233	}
