// Technisches-SEO-Audit über das gerenderte HTML (Dev-Server :3100).
// Aufruf: node audit.mjs <pfad1> <pfad2> ...  oder ohne Argumente: Standard-Stichprobe.
const BASE = "http://localhost:3100";

const args = process.argv.slice(2);
const PFADE = args.length ? args : [
  "/", "/de", "/at", "/ch", "/en",
  "/freiflaeche", "/ch/freiflaeche", "/agri-pv", "/ch/agri-pv",
  "/flaeche-verpachten", "/dachflaeche-verpachten", "/landwirte", "/kommunen", "/investoren",
  "/bestandsanlagen", "/regionen", "/de/regionen", "/at/regionen", "/regionen/bayern", "/regionen/tirol",
  "/projektboerse", "/rechner", "/rechner/pacht", "/rechner/solarpark", "/flaechencheck", "/at/flaechencheck",
  "/energiegemeinschaften", "/at/energiegemeinschaften", "/ch/energiegemeinschaften",
  "/marktdaten", "/ratgeber", "/wissen/lexikon", "/faq", "/en/faq",
  "/unternehmen", "/referenzen", "/kontakt", "/termin", "/impressum",
  "/virtuelles-kraftwerk", "/reststrom", "/energie-live", "/grossspeicher", "/solarcarport",
  "/prozess", "/warum-oekoinvest", "/genossenschaft", "/quellen", "/newsletter",
  "/en/rechner/pacht", "/en/flaeche-verpachten",
];

const dec = (s) => s
  .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, " ");

function attr(tag, name) {
  const m = new RegExp(`${name}\\s*=\\s*"([^"]*)"`, "i").exec(tag);
  return m ? dec(m[1]) : null;
}

async function pruefe(pfad) {
  let res;
  try { res = await fetch(BASE + pfad, { redirect: "manual" }); }
  catch (e) { return { pfad, fehler: String(e) }; }
  const status = res.status;
  if (status >= 300 && status < 400) return { pfad, status, ziel: res.headers.get("location") };
  const html = await res.text();
  const kopf = html.split(/<body[\s>]/i)[0];
  const body = html.slice(kopf.length);

  const titleM = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(kopf);
  const title = titleM ? dec(titleM[1]).trim() : null;
  const metas = kopf.match(/<meta\b[^>]*>/gi) || [];
  const desc = metas.map((t) => (attr(t, "name") === "description" ? attr(t, "content") : null)).find(Boolean) || null;
  const robots = metas.map((t) => (attr(t, "name") === "robots" ? attr(t, "content") : null)).find(Boolean) || null;
  const links = kopf.match(/<link\b[^>]*>/gi) || [];
  const canonical = links.map((t) => (attr(t, "rel") === "canonical" ? attr(t, "href") : null)).find(Boolean) || null;
  const hreflang = {};
  for (const t of links) if (attr(t, "rel") === "alternate" && attr(t, "hreflang")) hreflang[attr(t, "hreflang")] = attr(t, "href");

  // Überschriften in Dokumentreihenfolge
  const hs = [...body.matchAll(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi)].map((m) => ({
    stufe: +m[1],
    text: dec(m[2].replace(/<[^>]+>/g, "")).replace(/\s+/g, " ").trim().slice(0, 80),
  }));
  const h1 = hs.filter((h) => h.stufe === 1);
  // Hierarchie: Sprünge nach unten um >1 Stufe
  const spruenge = [];
  let vorher = 0;
  for (const h of hs) {
    if (vorher && h.stufe > vorher + 1) spruenge.push(`h${vorher}→h${h.stufe} "${h.text.slice(0, 40)}"`);
    vorher = h.stufe;
  }

  // JSON-LD-Typen
  const ld = [...html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)].flatMap((m) => {
    try {
      const d = JSON.parse(m[1]);
      const liste = Array.isArray(d) ? d : d["@graph"] ? d["@graph"] : [d];
      return liste.map((o) => o["@type"]).flat();
    } catch { return ["PARSE-FEHLER"]; }
  });

  // Bilder ohne alt (img-Tags ohne alt-Attribut; alt="" ist ok = dekorativ)
  const imgs = body.match(/<img\b[^>]*>/gi) || [];
  const ohneAlt = imgs.filter((t) => !/\balt\s*=/i.test(t)).map((t) => (attr(t, "src") || "").slice(0, 90));

  return {
    pfad, status, title, desc: desc ? desc.slice(0, 120) : null, robots, canonical,
    hreflang, h1: h1.map((h) => h.text), anzahlH1: h1.length, spruenge, ld, ohneAlt,
  };
}

const ergebnisse = [];
for (const p of PFADE) ergebnisse.push(await pruefe(p));
console.log(JSON.stringify(ergebnisse, null, 1));

