// Findet: verwaiste Seiten (keine eingehenden Links), doppelte title/description.
import { execFileSync } from "node:child_process";
import { alleSchluessel, SEITEN } from "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/lib/land/seiten.js";

const BASE = "http://127.0.0.1:3100";
const dec = (s) => s.replace(/&amp;/g, "&").replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"');

const seiten = alleSchluessel();
const ausgehend = {}; // pfad -> Set interner Ziele (normalisiert, ohne Präfix)
const meta = {};

function hole(pfad) {
  for (let v = 0; v < 3; v++) {
    try { return execFileSync("curl", ["-s", "--max-time", "120", BASE + pfad], { maxBuffer: 64 * 1024 * 1024 }).toString("utf8"); }
    catch { }
  }
  return null;
}

for (const p of seiten) {
  const html = hole(p);
  if (!html) { meta[p] = { fehler: true }; continue; }
  const titleM = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html);
  const descM = /<meta[^>]*name="description"[^>]*content="([^"]*)"/i.exec(html);
  meta[p] = { title: titleM ? dec(titleM[1]).trim() : null, desc: descM ? dec(descM[1]).trim() : null };
  const hrefs = [...html.matchAll(/<a\b[^>]*href="(\/[^"#?]*)[^"]*"/gi)].map((m) => m[1]);
  const ziele = new Set();
  for (let h of hrefs) {
    h = h.replace(/\/$/, "") || "/";
    // Präfixe entfernen
    h = h.replace(/^\/en(?=\/|$)/, "") || "/";
    h = h.replace(/^\/(de|at|ch)(?=\/|$)/, "") || "/";
    if (h !== p) ziele.add(h);
  }
  ausgehend[p] = [...ziele];
}

// eingehende Links
const eingehend = Object.fromEntries(seiten.map((s) => [s, 0]));
for (const [von, ziele] of Object.entries(ausgehend)) {
  for (const z of ziele) if (z in eingehend) eingehend[z]++;
}

const verwaist = seiten.filter((s) => s !== "/" && eingehend[s] === 0);
const titles = {};
const descs = {};
for (const [p, m] of Object.entries(meta)) {
  if (m.title) (titles[m.title] ||= []).push(p);
  if (m.desc) (descs[m.desc] ||= []).push(p);
}
const dupTitle = Object.entries(titles).filter(([, v]) => v.length > 1);
const dupDesc = Object.entries(descs).filter(([, v]) => v.length > 1);
const ohneTitle = Object.entries(meta).filter(([, m]) => !m.fehler && !m.title).map(([p]) => p);
const ohneDesc = Object.entries(meta).filter(([, m]) => !m.fehler && !m.desc).map(([p]) => p);
const fehler = Object.entries(meta).filter(([, m]) => m.fehler).map(([p]) => p);

console.log(JSON.stringify({ anzahl: seiten.length, verwaist, eingehendWenig: seiten.filter((s) => s !== "/" && eingehend[s] > 0 && eingehend[s] <= 1), dupTitle, dupDesc, ohneTitle, ohneDesc, fehler, ausgehend }, null, 1));

