// Screenshot einzelner Seitenabschnitte: node blockshot.mjs <url> <text-im-abschnitt> <datei>
import { chromium } from "playwright";
const [url, text, datei] = process.argv.slice(2);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto(url, { waitUntil: "load", timeout: 180000 });
await page.waitForTimeout(1200);
await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 3000 }).catch(() => {});
const ziel = page.locator(`text=${text}`).first();
await ziel.scrollIntoViewIfNeeded({ timeout: 15000 });
await page.waitForTimeout(800);
await page.screenshot({ path: datei });
await browser.close();
console.log("ok", datei);

